n25412.content:
\begin{definition}[Lebesgue conditional expectation]
  \label{def:lebesgue-cond-exp}
  % \uses{}
  \lean{MeasureTheory.condLExp}
  \leanok{}

  The {\bf conditional expectation} of a $\mathcal X$-measurable function $f : X \to [0, \infty]$ is
  \[\mu[f | \mathcal B] = ??\]
\end{definition}

n25413.content:
\begin{lemma}[Characterisation of the Lebesgue conditional expectation]
  \label{lem:lebesgue-cond-exp-char}
  \uses{def:lebesgue-cond-exp}
  \lean{MeasureTheory.ae_eq_condLExp}
  \leanok{}

  If $f : X \to [0, \infty]$ is a $\mathcal X$-measurable function, then $\mu[f | \mathcal B]$ is the $\mu$-ae unique $\mathcal B$-measurable function $X \to [0, \infty]$ such that
  \[\int_B \mu[f | \mathcal B]\ \partial\mu = \int_B f\ \partial\mu\]
  for all $B \in \mathcal B$.
\end{lemma}

n25415.content:
\begin{definition}[Juxtaposition]
    \label{def:juxtaposition}
    \lean{juxt}
    \leanok{}

    Let $E$ and $S$ be sets. Let $\Delta\in\mathcal{P}(S)$, and let $\omega\in E^S$. We define
    \begin{align}
        \juxtOper_{\omega} : E^\Delta&\to E^S\\
        \zeta&\mapsto \delta\mapsto\begin{cases}
            \zeta_\delta & \delta\in\Delta\\
            \omega_\delta & \delta\notin\Delta
        \end{cases}
    \end{align}
    to be the \textbf{juxtaposition of $\zeta$ and $\omega$} (for each $\zeta\in E^\Delta$).
\end{definition}

n25416.content:
\begin{definition}[Cylinder events]
    \label{def:cylinder-event}
    \lean{MeasureTheory.cylinderEvents}
    \leanok{}

    Let $(E,\mathcal{E})$ be a measurable space, and let $S$ be a set. Then,
    \begin{align}
        \mathcal{F}:\mathcal{P}(S)&\to \left\{ \text{sigma algebras on } E^S \right\}\\
        \Delta&\mapsto \sigma(\{\text{proj}_\delta:E^S\to E\mid \delta\in \Delta\})
    \end{align}
    defines the \textbf{cylinder events in }$\Delta$ (for each $\Delta\in\mathcal{P}(S)$),
    where each $\text{proj}_\delta$ is the coordinate projection at coordinate $\delta$.
\end{definition}

n25417.content:
\begin{definition}[Kernel]
    \label{def:kernel}
    \lean{ProbabilityTheory.Kernel}
    \leanok{}

    Let $(X,\mathcal X)$ and $(Y,\mathcal{Y})$ be measurable spaces. Then,
    \[\text{Ker}_{\mathcal{Y},\mathcal X}:=\left\{\pi:\mathcal X\times Y\to[0,\infty]~\middle\vert~ \forall y\in Y,\pi(\cdot\mid y)\in\mathfrak{M}(X,\mathcal X);~\forall A\in\mathcal X,\pi(A\mid\cdot)\text{ is }\mathcal{Y}\text{-measurable}\right\}\]
    defines the set of \textbf{kernels from $\mathcal{Y}$ to $\mathcal X$}, where $\mathfrak{M}(X,\mathcal X)$ is the space of measures on $X$.
\end{definition}

n25418.content:
\begin{definition}[Markov kernel]
    \label{def:markov-ker}
    \uses{def:kernel}
    \lean{ProbabilityTheory.IsMarkovKernel}
    \leanok{}

    Let $(X,\mathcal X)$ and $(Y,\mathcal{Y})$ be measurable spaces. We say that $\pi\in\text{Ker}_{\mathcal{Y},\mathcal X}$ is a \textbf{Markov kernel} iff $\pi(X\mid \cdot)=1$.
\end{definition}

n25419.content:
\begin{definition}[Proper kernel]
    \label{def:proper-ker}
    \uses{def:kernel}
    \lean{ProbabilityTheory.Kernel.IsProper}
    \leanok{}

    $\pi$ is \textbf{proper} iff $\pi(A\cap B\mid x)=\pi(A\mid x)\cdot\mathbf{1}_B(x)$ for all $A\in\mathcal X$, $B\in\mathcal B$ and $x\in X$.
\end{definition}

n25420.content:
\begin{lemma}[Lebesgue integral characterisation of proper kernels]
    \label{lem:proper-ker-lintegral}
    \uses{def:proper-ker}
    \lean{ProbabilityTheory.Kernel.IsProper.lintegral_mul}
    \leanok{}

    If $\pi$ is proper, then
    \[\int f(x) g(x)\ \pi(dx\mid x_0) = g(x_0)\int f(x)\ \pi(dx\mid x_0)\]
    for all $x_0 \in X$ and functions $f, g : X \to [0, \infty]$ such that $f$ is $\mathcal X$-measurable, $g$ is $\mathcal B$-measurable.
\end{lemma}

n25422.content:
\begin{lemma}[Integral characterisation of proper kernels]
    \label{lem:proper-ker-integral}
    \uses{def:proper-ker}
    \lean{ProbabilityTheory.Kernel.IsProper.integral_bdd_mul}
    \leanok{}

    If $\pi$ is a proper Markov kernel and $g$ is a bounded function, then
    \[\int f(x) g(x)\ \pi(dx\mid x_0) = g(x_0)\int f(x)\ \pi(dx\mid x_0)\]
    for all $x_0 \in X$ and functions $f, g : X \to \mathbb R$ such that $f$ is bounded $\mathcal X$-measurable and $g$ is bounded $\mathcal B$-measurable.
\end{lemma}

n25424.content:
\begin{definition}[Conditional expectation kernel]
    \label{def:cond-exp-ker}
    \uses{def:kernel}
    \lean{ProbabilityTheory.condExpKernel, ProbabilityTheory.Kernel.IsCondExp}
    \leanok{}

    Let $\mu\in\mathfrak{M}(X,\mathcal X)$. Then, $\pi\in\text{Ker}_{\mathcal B,\mathcal X}$ is a \textbf{conditional expectation kernel for $\mu$} if $\mu(A\mid \mathcal B)=\pi(A\mid\cdot)$ $\mu$-a.e.
\end{definition}

n25425.content:
\begin{lemma}[Lebesgue integral characterisation of proper conditional expectation kernels]
    \label{lem:cond-exp-proper-ker-lintegral}
    \uses{def:cond-exp-ker, def:proper-ker}
    % \lean{}
    % \leanok

    If $\pi \in \text{Ker}_{\mathcal B, \mathcal X}$ is a conditional expectation kernel for $\mu$, then
    \[\mu[f\mid \mathcal B] = \int f(x)\ \pi(\partial x\mid\cdot)\ \mu\text{-a.e.}\]
    for all $\mathcal X$-measurable functions $f : X \to [0, \infty]$.
\end{lemma}

n25427.content:
\begin{lemma}[Integral characterisation of proper conditional expectation kernels]
    \label{lem:cond-exp-proper-ker-integral}
    \uses{def:cond-exp-ker, def:proper-ker}
    \lean{ProbabilityTheory.Kernel.condExp_ae_eq_integral}
    \leanok

    If $\pi \in \text{Ker}_{\mathcal B, \mathcal X}$ is a conditional expectation kernel for $\mu$, then
    $$\mu(f\mid \mathcal B) = \int f(x)\ \pi(\partial x\mid\cdot)\ \mu\text{-a.e.}$$
    for all bounded $\mathcal X$-measurable functions $f : X \to \mathbb R$.
\end{lemma}

n25429.content:
\begin{lemma}[Characterisation of proper conditional expectation kernels, Remark 1.20]
    \label{lem:cond-exp-proper-ker-bind}
    \uses{def:cond-exp-ker}
    \lean{ProbabilityTheory.Kernel.isCondExp_iff_bind_eq_left}
    \leanok

    Let $\mu\in\mathfrak{M}(X,\mathcal X)$ be a finite measure and let $\pi\in\text{Ker}_{\mathcal B,\mathcal X}$ be a proper kernel. Then,
    $$\pi \text{ is a conditional expectation kernel for }\mu \iff \mu\pi = \mu$$
\end{lemma}

n25430.content:
\begin{proof}
    \uses{lem:lebesgue-cond-exp-char}
    \leanok

    By the characterisation of conditional expectation,
    $$\pi \text{ is a conditional expectation kernel for }\mu \iff \forall A \in \mathcal X, \forall B \in \mathcal B, \mu(A \cap B) = \int_B \pi(A|\cdot)\ \partial\mu$$
    By properness of $\pi$,
    $$\int_B \pi(A|\cdot)\ \partial\mu = \mu\pi(A \cap B)$$
    Hence
    \begin{align}
        \pi \text{ is a cond. exp. kernel with respect to }\mu
        & \iff \forall A \in \mathcal X, \forall B \in \mathcal B, \mu(A \cap B) = \mu\pi(A \cap B) \\
        & \iff \forall A \in \mathcal X, \mu(A) = \mu\pi(A) \\
        & \iff \mu = \mu\pi
    \end{align}
\end{proof}

n25431.content:
\begin{definition}[Specification]
    \label{def:spec}
    \uses{def:cylinder-event, def:kernel}
    \lean{Specification}
    \leanok{}

    A {\bf specification} is a family of kernels $\gamma : \Finset S \to \Ker_{\mathcal{F}_{S\setminus\Lambda}, \mathcal{E}^S}$ which is {\bf consistent}, in the sense that
    \[\forall \Lambda_1, \Lambda_2 \in \Finset(S), \Lambda_1 \subseteq \Lambda_2 \implies \gamma_{\Lambda_1} \circ_k \gamma_{\Lambda_2} = \gamma_{\Lambda_2}\]
\end{definition}

n25432.content:
\begin{definition}[Independent specification]
    \label{def:indep-spec}
    \uses{def:spec}
    \lean{Specification.IsIndep, Specification.IsIndep.bind_eq_union}
    \leanok{}

    A specification $\gamma$ is \textbf{independent} iff
    \[\forall \Lambda_1, \Lambda_2 \in \Finset(S), \gamma_{\Lambda_1} \circ_k \gamma_{\Lambda_2} = \gamma_{\Lambda_1\cup\Lambda_2}\]
\end{definition}

n25433.content:
\begin{definition}[Markov specification]
    \label{def:markov-spec}
    \lean{Specification.IsMarkov}
    \leanok{}
    \uses{def:spec}

    A specification $\gamma$ is a \textbf{Markov specification} iff $\gamma_\Lambda$ is a probability kernel for every $\Lambda \in \Finset(S)$.
\end{definition}

n25434.content:
\begin{definition}[Proper specification]
    \label{def:proper-spec}
    \uses{def:spec, def:proper-ker}
    \lean{Specification.IsProper}
    \leanok{}

    A specification $\gamma$ is \textbf{proper} iff the kernel $\gamma_\Lambda$ is proper for every $\Lambda \in \Finset(S)$.
\end{definition}

n25435.content:
\begin{definition}[Gibbs measures]
    \label{def:gibbs-meas}
    \uses{def:spec, def:cond-exp-ker}
    \lean{Specification.IsGibbsMeasure}
    \leanok
    Given a specification $\gamma$, a \textbf{Gibbs measures specified by $\gamma$} is a measure $\nu \in \mathfrak{M}(E^S, \mathcal{E}^S)$ such that $\gamma_\Lambda(A|\cdot)$ is a conditional expectation kernel for $\nu$ for all $A \in \mathcal E^S$ and $\Lambda \in \Finset(S)$.
\end{definition}

n25436.content:
\begin{lemma}[Characterisation of Gibbs measures, Remark 1.24]
    \label{lem:gibbs-meas-tfae}
    \uses{def:gibbs-meas, def:proper-spec}
    \lean{Specification.isGibbsMeasure_iff_forall_bind_eq, Specification.isGibbsMeasure_iff_frequently_bind_eq}
    \leanok

    Let $\gamma$ be a {\it proper} specification with parameter set $S$ and state space $(E, \mathcal{E})$, and let $\nu\in\mathfrak{P}(E^S, \mathcal{E}^S)$. TFAE:
    \begin{enumerate}
        \item $\nu\in\mathcal{G}(\gamma)$.
        \item $\gamma_\Lambda\circ_m\nu = \nu$ for all $\Lambda\in\Finset(S)$.
        \item $\gamma_\Lambda\circ_m\nu = \nu$ frequently as $\Lambda \to S$.
    \end{enumerate}
\end{lemma}

n25437.content:
\begin{proof}
    \uses{lem:cond-exp-proper-ker-lintegral}
    \leanok

    1 is equivalent to 2 by Lemma \ref{lem:cond-exp-proper-ker-lintegral}. 2 trivially implies 3. Now, 3 implies 2 because for each $\Lambda$ there exists some $\Lambda' \supseteq \Lambda$ such that
    $\gamma_{\Lambda'}\circ_k\nu = \nu$. Then
    $$\nu\gamma_\Lambda = \nu\gamma_{\Lambda'}\gamma_\Lambda = \nu\gamma_{\Lambda'} = \nu$$
\end{proof}

n25438.content:
\begin{definition}[Product probability measure]
    \label{def:product-probability-measure}
    \lean{MeasureTheory.Measure.infinitePi}
    \leanok{}

    Let $I$ be a set. Suppose for each $i\in I$ that $(\Omega_i,\mathcal B_i,P_i)$ is a probability space. Then, $P:=\bigotimes_{i\in I}P_i$ is a well-defined product probability measure on $\prod_{i\in I}\Omega_i$.
\end{definition}

n25439.content:
\begin{definition}[Independent Specification with Single Spin Distribution (ISSSD)]
    \label{def:isssd}
    \uses{def:juxtaposition}
    \lean{Specification.isssdFun}
    \leanok

    The \textbf{Independent Specification with Single Spin Distribution $\nu$} is
    \begin{align}
        \ISSSD:\mathfrak{P}(E, \mathcal{E})&\to\Finset(S)\to\mathcal{E}^S\times E^S\to\overline{\mathbb{R}_{\geq0}}\\
        \nu&\mapsto\Lambda\mapsto(A\mid\omega)\mapsto\left(\nu^\Lambda\left(\juxtOper_{\omega}^{-1}(A)\right)\right)
    \end{align}
    defines the \textbf{Independent Specification with Single Spin Distribution with $\nu$} (for each $\nu\in\mathfrak{P}(E, \mathcal{E})$), where $\nu^\Lambda$ is the usual product measure.
\end{definition}

n25442.content:
\begin{definition}[ISSSDs are specifications]
    \label{def:isssd-spec}
    \uses{lem:isssd-indep, def:spec}
    \lean{Specification.isssd}
    \leanok

    $\ISSSD(\nu)$ is a specification.
\end{definition}

n25443.content:
\begin{lemma}[ISSSDs are proper specifications]
    \label{lem:isssd-proper-spec}
    \uses{def:isssd, def:proper-spec}
    \lean{Specification.IsProper.isssd}
    \leanok

    $\ISSSD(\nu)$ is a proper specification.
\end{lemma}

n25444.content:
\begin{proof}
    \uses{def:isssd-spec}
    % \leanok

    We already know it's a specification. Properness is immediate.
\end{proof}

n25445.content:
\begin{lemma}[Uniqueness of a Gibbs measure specified by an ISSSD]
    \label{lem:isssd-gibbs-meas-uniqueness}
    \uses{def:gibbs-meas, def:isssd-spec}
    \lean{Specification.isGibbsMeasure_isssd_iff}
    \leanok

    There is at most one Gibbs measure specified by $\ISSSD(\nu)$.
\end{lemma}

n25447.content:
\begin{lemma}[Existence of a Gibbs measure specified by an ISSSD]
    \label{lem:isssd-gibbs-meas-existence}
    \uses{def:gibbs-meas, def:product-probability-measure, def:isssd-spec}
    \lean{Specification.isGibbsMeasure_isssd_infinitePi}
    \leanok{}

    The product measure $\nu^S$ is a Gibbs measure specified by $\ISSSD(\nu)$.
\end{lemma}

n25449.content:
\begin{definition}[Modifier]
    \label{def:modif}
    \uses{def:spec}
    \lean{Specification.IsModifier, Specification.modification}
    \leanok{}

    A {\bf modifier of $\gamma$} is a family
    \[\rho : \Finset(S) \to \Omega \to [0, \infty[\]
    such that the corresponding family of kernels $\rho\gamma$ is a specification.
\end{definition}

n25450.content:
\begin{lemma}[Modifier of a modifier]
    \label{lem:modif-modif}
    \uses{def:modif}
    \lean{Specification.modification_modification}
    \leanok{}

    Modifying a specification $\gamma$ by $\rho_1$ then $\rho_2$ is the same as modifying it by their product.
\end{lemma}

n25452.content:
\begin{lemma}[A modifier of a proper specification is proper]
    \label{lem:modif-proper}
    \uses{def:modif, def:proper-spec}
    \lean{Specification.IsProper.modification}
    \leanok{}

    If $\gamma$ is a specification and $\rho$ a modifier of $\gamma$, then $\rho\gamma$ is a proper specification.
\end{lemma}

n25453.content:
\begin{proof}
    \uses{lem:proper-ker-lintegral}
    \leanok

    For all $\Lambda \in \Finset(S)$, $A \in \mathcal E^S$, $B \in \mathcal{F}_{S\setminus\Lambda}$, $\eta : S \to E$, we want to prove
    $$(\rho\gamma)_\Lambda(A \cap B | \eta) = 1_B(\eta) (\rho\gamma)_\Lambda(A B | \eta)$$
    Expanding out, this is equivalent to
    $$\int_{\zeta \in A \cap B} \rho_\Lambda(\zeta)\ d(\gamma_\Lambda(\eta)) = 1_B(\eta) \int_{\zeta \in A} \rho_\Lambda(\zeta)\ d(\gamma_\Lambda(\eta))$$
    which is true by Lemma \ref{lem:proper-ker-lintegral} with $f = 1_A\rho_\Lambda$, $g = 1_B$.
\end{proof}

n25454.content:
\begin{lemma}[Every specification is a modification of some ISSSD, Remark 1.28.5]
    \label{lem:exists-modif-isssd}
    \uses{def:modif, def:isssd}
    % \lean{}
    % \leanok

    If $E$ is countable, $\nu$ is the counting measure and $\gamma$ is any specification, then
    $$\rho_\Lambda(\eta) = \gamma_\Lambda(\{\sigma_\Lambda = \eta_\Lambda\} | \eta)$$
    is a modifier from $\ISSSD(\nu)$ to $\gamma$.
\end{lemma}

n25455.content:
\begin{proof}
    % \uses{}
    % \leanok

    For all $\Lambda \in \Finset(S)$, $A$ measurable, $\eta : S \to E$, we have
    \begin{align}
        (\rho\ISSSD(\nu))_\Lambda(A|\eta)
        & = \int_\zeta \rho_\Lambda(\zeta) \ISSSD(\nu)(d\zeta|\eta) \\
        & = \int_\zeta \gamma_\Lambda(\{\sigma_\Lambda = \eta_\Lambda\} | \eta) \ISSSD(\nu)(d\zeta|\eta) \\
        & = \gamma_\Lambda(A|\eta)
    \end{align}
\end{proof}

n25456.content:
\begin{proposition}[Characterisation of modifiers, Proposition 1.30.1]
    \label{prop:modif-char}
    \uses{def:modif, def:proper-spec, def:markov-spec}
    \lean{Specification.isModifier_iff_ae_eq}
    \leanok{}

    If $\rho$ is a family of measurable densities and $\gamma$ is a proper Markov specification, then TFAE
    \begin{enumerate}
        \item $\rho$ is a modifier of $\gamma$
        \item For all $\Lambda_1, \Lambda_2$ with $\Lambda_1 \subseteq \Lambda_2$ and all $\eta : S \to E$, we have
        \[\rho_{\Lambda_2} = \rho_{\Lambda_1}\cdot (\gamma_{\Lambda_1} \rho_{\Lambda_2}) \quad \gamma_{\Lambda_2}(\cdot|\eta)\text{-a.e.}\]
    \end{enumerate}
    Georgii's (1.30) is the $\lambda$-specification case, and assumes $\lambda_\Lambda\rho_\Lambda=1$ from the start.
\end{proposition}

n25458.content:
\begin{proposition}[Characterisation of modifiers of independent specifications, Proposition 1.30.2]
    \label{prop:modif-indep-char}
    \uses{def:modif, def:indep-spec, def:proper-spec, def:markov-spec}
    \lean{Specification.isModifier_iff_ae_comm}
    \leanok{}

    If $\rho$ is a family of measurable densities, $\gamma$ is a proper Markov independent specification,
    and $\gamma_\Lambda(\rho_\Lambda)=1$ for all $\Lambda$, then TFAE
    \begin{enumerate}
        \item $\rho$ is a modifier of $\gamma$
        \item For all $\Lambda_1, \Lambda_2$ with $\Lambda_1 \subseteq \Lambda_2$, $\eta : S \to E$ and $\gamma_{\Lambda_2 \setminus \Lambda_1}(\cdot|\alpha)$-almost all $\eta_2 : S \to E$, we have
        \[\rho_{\Lambda_2}(\zeta_1)\rho_{\Lambda_1}(\zeta_2) = \rho_{\Lambda_2}(\zeta_2) \rho_{\Lambda_1}(\zeta_1)\]
        for $\gamma_{\Lambda_1}(\cdot|\eta_2) \times \gamma_{\Lambda_1}(\cdot|\eta_2)$-almost all $(\zeta_1, \zeta_2)$.
    \end{enumerate}
\end{proposition}

n25460.content:
\begin{definition}[Premodifier, Definition 1.31]
    \label{def:premodif}
    % \uses{}
    \lean{Specification.IsPremodifier}
    \leanok

    A family of measurable functions $h_\Lambda : (S \to E) \to [0, \infty[$ is a {\bf premodifier} if
    $$h_{\Lambda_2}(\zeta)h_{\Lambda_1}(\eta) = h_{\Lambda_1}(\zeta)h_{\Lambda_2}(\eta)$$
    for all $\Lambda_1 \subseteq \Lambda_2$ and all $\zeta, \eta : S \to E$ such that $\zeta_{\Lambda_1^c} = \eta_{\Lambda_1^c}$.
\end{definition}

n25461.content:
\begin{lemma}[Modifiers are premodifiers]
    \label{lem:modif-premodif}
    \uses{def:modif, def:premodif}
    % \lean{}
    % \leanok
    If $\rho$ is a modifier of $\ISSSD(\nu^S)$, then it is a premodifier if any of the following conditions hold:
    \begin{enumerate}
        \item $E$ is countable and $\nu$ is equivalent to the counting measure.
        \item $E$ is a second countable Borel space.
        \item $\nu$ is everywhere dense.
        \item For all $\Lambda_1 \subseteq \Lambda_2$ and all $\eta : S \to E$, $\zeta \mapsto \rho_{\Lambda_1}(\zeta \eta_{\Lambda_1^c})$ is continuous on $E^{\Lambda_1}$.
    \end{enumerate}
\end{lemma}

n25463.content:
\begin{lemma}[Premodifiers give rise to modifiers, Remark 1.32]
    \label{lem:premodif-modif}
    \uses{def:modif, def:premodif}
    \lean{Specification.IsPremodifier.isModifier_div}
    \leanok
    If $h$ is a premodifier and $\nu$ is such that $0 < \nu_\Lambda h_\Lambda < \infty$ for all $\Lambda$, then
    $$\rho_\Lambda := \frac{h_\Lambda}{\ISSSD(\nu)_\Lambda h_\Lambda}$$
    is a modifier of $\ISSSD(\nu)$.
\end{lemma}

n25464.content:
\begin{proof}
    \uses{prop:modif-char}

    Georgii goes through (1.30)(c). The Lean proof uses (1.30)(b), which is equivalent.
\end{proof}

